# Function to check if a number is prime
def is_prime(n):
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    w = math.floor(math.sqrt(n))
    while i <= w:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def find_r_and_p(w1, w2, m):
    words = [w1, w2]
    n = len(w1)

    # Check all primes in the range [m, 10^9]
    for p in range(m, 10**9):
        if is_prime(p):
            if n <= p - 1:
                # Calculate the corresponding r values for the maximum prime
                r_values = [r for r in range(2, p - 1)]

                # Sort the r values based on their index in the range [2, p-2]
                bisect.insort(r_values, 2)
                for r in r_values:
