import sys

def calculate_bitwise_operations_go(node):
    """Calculate operations from node_is_XOR and node_is_AND."""
    return node | (node << 1)

def calculate_bitwise_operations_tr(node):
    """Calculate operations from node_is_XOR and node_is_AND."""
    return node & (node >> 1)

def calculate_new_weight(node, go_data, tr_data):
    """Calculate the weight of a new edge from \'node\'."""
    return calculate_bitwise_operations_go(node) + calculate_bitwise_operations_tr(node)

def calculate_spanning_tree_weights(go_data, tr_data):
    """Calculate the total weight of the MST for the given data."""
    previous_node, current_node, max_weight = 0, 0, 0

    go_data.sort()
    tr_data.sort()

    # Build the MST according to the sorted weights
    for node in range(1, max(go_data[-1], tr_data[-1]) + 1):
        if go_data[-1] <= node:
            max_weight += calculate_spanning_tree_weights(
                calculate_new_weight(node, go_data, tr_data), 
                [go_data[go_data.index(node) + 1] if node != go_data[-1] else -sys.maxsize, 
                 tr_data[tr_data.index(node) + 1] if node != tr_data[-1] else -sys.maxsize]
            )
        else:
            max_weight += calculate_new_weight(node, go_data, tr_data)

    return max_weight

if __name__ == "__main__":
    T = int(sys.stdin.readline().strip())
    for _ in range(T):
        N = int(sys.stdin.readline().strip())
        go_data = list(map(int, sys.stdin.readline().strip().split()))
        tr_data = list(map(int, sys.stdin.readline().strip().split()))
        print(calculate_spanning_tree_weights(go_data, tr_data))
