from typing import List

def max_avg_distance(speeds: List[tuple], points: List[tuple]) -> tuple:
    pi = [lambda p, q: (p+speeds[i]%100, q-speeds[i]%100) for i in range(len(points))]
    weight = [[0]*(len(points)) for _ in range(len(points))]
    for i, point in enumerate(points):
        for j, (x, y) in enumerate(points):
            distance = abs(x - point[0]) + abs(y - point[1])
            if distance > speeds[i]:
                continue
            speed = speeds[i] - distance
            if speed % 100:
                pi_queue = min(pi_const(pi[i], speed % 100, x, y))
                weight[j][i] = pi_queue
            else:
                weight[j][i] = pi_const(pi[i], 0, x, y)
    return [
        [x, y]
        for i, pi_sum in enumerate(weight)
        for x, y in points[pi_sum.index(1)]
        if i < points[pi_sum.index(1)].index(x, y) or i == 0
    ]

def pi_const(pi, p, x, y):
    dx, dy = pi(x, y)
    p = p % 100
    if p < 0:
        p += 100
    if dx < 0:
        dx -= p
    else:
        dx = min(dx, p)
    if dy < 0:
        dy -= p
    else:
        dy = min(dy, p)
    return abs(dx - x) + abs(dy - y)

def solve(N: int, fans: List[tuple]) -> str:
    points = [
        (xi, yi)
        for i, (xi, yi, vi) in enumerate(fans)
        if vi > 0 or (all(speed_que < vi-xi-yi for speed_que in speed_que) for speed_que in fans[i+1:])
    ]
    points.sort()
    best = max_avg_distance([fan[2] for fan in fans], points)
    return '\n'.join(str(x) for x, y in best)

