        store_times.append((x_i, y_i, z_i, 'open'))
        store_times.append((x_i, y_i, z_i, 'closed'))
    store_times.sort()
    return x_max, y_max, z_max, store_data, store_times

def solve(x_max, y_max, z_max, store_data, store_times):
    # Process store times to find confirm periods based on data
    store_open = set()
    store_closed = set()
    for x, y, z, status in store_data + store_times:
        if status == 'open':
            store_open.add((x, y, z))
        else:
            store_closed.add((x, y, z))

    # There's an inconsistency if there are open and closed periods at the same time
    # This check requires only taking sets with the most recent open and closed values (assuming ordered, most recent)
    max_open_time = None
    for x, y, z in store_open:
        if max_open_time is None or max_open_time[2] < z:
            max_open_time = (x, y, z)

    max_closed_time = None
    for x, y, z in store_closed:
        if max_closed_time is None or max_closed_time[2] > z:
            max_closed_time = (x, y, z)

