from collections import defaultdict

def parse_commands(time_distance_tuples):
    """
    Parses the given time, x, and y tuples into a program.
    """
    last_x, last_y = 0, 0
    current_x, current_y = 0, 0

    visited = defaultdict(lambda: False)
    index = 0

    commands = []

    while index < len(time_distance_tuples):
        current_x, current_y = time_distance_tuples[index][1], time_distance_tuples[index][2]
        if current_x != last_x or current_y != last_y:
            visited[(last_x, last_y)] = True
            commands.append(time_distance_tuples[index])
            last_x, last_y = current_x, current_y
        index += 1

    for command in commands:
        if command[3] == 'R':
            commands.append((command[0] + 1, command[1], command[2], 'R'))
        elif command[3] == 'L':
            commands.append((command[0] + 1, command[1], command[2], 'L'))
        elif command[3] == 'U':
            commands.append((command[0], command[1] - 1, command[2], 'U'))
        elif command[3] == 'D':
            commands.append((command[0], command[1], command[2], 'D'))

    for command in reversed(commands):
        if command[3] == 'R':
            commands.insert(0, (command[0] - 1, command[1], command[2], 'R'))
        elif command[3] == 'L':
            commands.insert(0, (command[0] - 1, command[1], command[2], 'L'))
        elif command[3] == 'U':
            commands.insert(0, (command[0], command[1] + 1, command[2], 'U'))
        elif command[3] == 'D':
            commands.insert(0, (command[0], command[1], command[2], 'D'))

    commands = commands[1:]

