        delta = [command[i]
                for i in range(3, len(command) + 1)
                if command[i] != 'R' and command[i] != 'L']
        program[index % 4 + 1:index + len(delta)] = delta
        index += len(delta)

    return ''.join([''.join([str(x % 4 + 1) for x in pair])
                    for pair in zip(*([x][i] for i in range(4) for x in zip(*commands)))])

