import math

class Graph:
    def __init__(self, n):
        self.n = n
        self.weights = [[] for _ in range(n)]

    def add_edge(self, u, v, weight):
        self.weights[u].append((v, weight))
        self.weights[v].append((u, weight))

    def max_spanning_tree(self):
        parent = [-1] * self.n
        dist = [-math.inf] * self.n
        adj = [[] for _ in range(self.n)]

        for u in range(self.n):
            for v, weight in self.weights[u]:
                adj[u].append((v, weight))

        dist[0] = 0
        for _ in range(self.n):
            min_u = -1
            min_dist = math.inf
            for v in range(self.n):
                if parent[v] != -1:
                    continue
                if dist[v] < min_dist:
                    min_u = v
                    min_dist = dist[v]

            if min_u == -1:
                break

            dist[min_u] = -math.inf
            for v, d in adj[min_u]:
                if parent[v] != -1:
                    continue
                new_dist = min_dist + d
                if new_dist < dist[v]:
                    dist[v] = new_dist
                    parent[v] = min_u

        total_weight = sum(d for u, v, d in adj if parent[u] == v)
        return total_weight

