def unique_pairs(n, m, edges):
    degree = defaultdict(int)
    for u, v, w in edges:
        degree[u] += 1
        degree[v] += 1

    digits = defaultdict(list)
    for node in range(n):
        for _ in range(degree[node]):
            digits[w[node]].append(node)

    result = 0
    for u in digits:
        for v in digits:
            if gcd(int(u), int(v)) != 1:
                continue
            x = int(u)
            y = int(v)
            product = x * y
            products = set()
            while product % 10 != 0:
                products.add(product)
                product /= 10
                product = int(product)
            for product in products:
                if product % m == 0:
                    result += 1

    return result

