    ans = [0] * n
    ans[0] = pow(s[0], 26, 1000000007)
    for i in range(1, n):
        for j in range(46):
            if s[i] < s[46 - j]:
                ans[i] = (ans[i] * rating_possible[j] + ans[i - 1]) % 1000000007
            else:
                ans[i] = (26 * ans[i - 1]) % 1000000007
    return ans[-1]

