import math

def max_spanning_tree(weights):
    n = len(weights)
    def find(parent, i):
        if parent[i] == i:
            return i
        else:
            return find(parent, parent[i])

    def union(parent, rank, x, y):
        xroot = find(parent, x)
        yroot = find(parent, y)
        if rank[xroot] < rank[yroot]:
            parent[xroot] = yroot
        elif rank[yroot] < rank[xroot]:
            parent[yroot] = xroot
        else:
            parent[yroot] = xroot
            rank[xroot] += 1

    parent = list(range(n))
    rank = [0 for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            union(parent, rank, i, j)
            x = weights[find(parent, i)][i] * weights[find(parent, j)][j]
            y = weights[find(parent, i)][j] * weights[find(parent, j)][i]
            weights[find(parent, i)][j] = x
            weights[find(parent, j)][i] = y
    print(sum(weights[find(parent, i)][j] for i in range(n) for j in range(n) if i < j))
