def solve(n, k, s):
    mod = 1000000007
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            dp[i][j] = dp[i-1][j]
            if s[i-1] < letters[j]:
                dp[i][j] = (dp[i][j] + dp[i-1][j-1]) % mod

