    dp[0] = 1
    for i in range(n):
        if s[i] > s[i + 1]:
            dp[i + 1] = (dp[i] * (n - i) // i) % (10**9 + 7)
    ans = 0
    for i in range(1, n + 1):
        if dp[i] < (k + 1) // 2:
            break
        j = min(n - i + 1, (k + 1) // 2 * dp[i])
        k -= j
        ans = (ans + dp[i] * dp[j]) % (10**9 + 7)
