def generate_primes_less_than(n):
    primes = []
    for num in range(2, n + 1):
        if all(num % i != 0 for i in range(2, int(num**0.5) + 1)):
            primes.append(num)
    return primes

def compute_hash(w, r, p):
    hash_val = 0
    for char in w:
        hash_val = (hash_val * (r % p) + ascii_lowercase.index(char)) % p
    return hash_val

def main():
    n, m = map(int, input().split())
    w1, w2 = input().strip(), input().strip()
    p = randint(m, 10**9)
    r = randint(2, p-2)


