        return compute_hash(w1, r, p) == compute_hash(w2, r, p)

    if is_equal_hash():
        return ' '.join([str(p), str(r)])

    prob_of_collision = 1
    for _ in range(n):
        r = randint(2, p-2)
        if is_equal_hash():
            prob_of_collision *= (r-2) / (p-2)
        elif is_equal_hash():
